        if (!machineMerge) return commit;
        sha = commit.parents[0];
    }
    console.warn('  ⚠️  park-reset walk: 10 machine merges deep without a ' +
        'substantive commit — keeping the park (fail closed)');
    return null;
}

function parkedSince(repoInfo, prNumber) {
