        })
    }));
    sm.action({ jobParams: { owner: 'a', repo: 'b', machineAuthor: 'ai-teammate',
                             rules: [RULES_VF.refresh] } });

    assert.equal(sm.capturedPrLabelRemoves.length, 0, 'unwalkable chain — park holds');
