                                  actors: { dd33ee44ff: { login: 'real-dev', date: '2026-09-30T15:00:00Z' } },
                                  parkedAt: '2026-09-30T14:00:00Z' })
        }));
        sm.action({ jobParams: { owner: 'a', repo: 'b', machineAuthor: 'ai-teammate',
