                   branch: 'feat/vf-' + n, headSha: '11ab22cd3' + n, author: 'guest-human' };
        if (extra) { for (var k in extra) { if (extra.hasOwnProperty(k)) it[k] = extra[k]; } }
        return it;
    }
    function vfCli(opts) {
        // Stub answers the three park probes keyed on command shape:
