    var capturedStatusMoves = [];
    var capturedJqls = [];
    var capturedCliCommands = [];
    var capturedCloses = [];
    var capturedPrMerges = [];
    var capturedPrLabelAdds = [];
    var capturedPrLabelRemoves = [];
    var capturedPrComments = [];
    var capturedEnvSets = [];
