                prStatus: { checkConclusion: 'none' }
            },
            onCliExecute: vfCli({ committers: { ff44556677: 'sm-silent-update' } })
        }));
        sm.action({ jobParams: { owner: 'a', repo: 'b', machineAuthor: 'ai-teammate',
