                                    tipLogin: 'another-human', tipDate: '2026-10-03T22:05:00Z' }),
            parkedAt: '2026-10-03T22:31:00Z'
        })
    }));
    sm.action({ jobParams: { owner: 'a', repo: 'b', machineAuthor: 'ai-teammate',
